import React, { useState } from "react";
import axios from "axios";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

const Login = () => {
  // Using window.location for navigation because the app uses a simple
  // pathname-based router (no react-router <Router> wrapper).
  const navigate = (to) => {
    window.location.pathname = to;
  };
  const [inputValue, setInputValue] = useState({ email: "", password: "" });
  const { email, password } = inputValue;
  const handleOnChange = (e) => {
    const { name, value } = e.target;
    setInputValue({ ...inputValue, [name]: value });
  };

  const handleError = (err) => toast.error(err, { position: "bottom-left" });
  const handleSuccess = (msg) =>
    toast.success(msg, { position: "bottom-left" });

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const resp = await axios.post(
        "http://localhost:3002/login",
        { ...inputValue },
        { withCredentials: true },
      );
      const { data, status } = resp;
      const { success, message } = data || {};
      if (success === true || status === 201) {
        handleSuccess(message || "User logged in successfully");
        setTimeout(() => navigate("/"), 800);
      } else {
        handleError(message || "Login failed");
      }
    } catch (error) {
      const msg =
        error?.response?.data?.message || error?.message || "Login failed";
      handleError(msg);
    }
    setInputValue({ email: "", password: "" });
  };

  return (
    <div className="form_container">
      <h2>Login Account</h2>
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="email">Email</label>
          <input
            type="email"
            name="email"
            value={email}
            placeholder="Enter your email"
            onChange={handleOnChange}
          />
        </div>
        <div>
          <label htmlFor="password">Password</label>
          <input
            type="password"
            name="password"
            value={password}
            placeholder="Enter your password"
            onChange={handleOnChange}
          />
        </div>
        <button type="submit">Submit</button>
        <span>
          Don't have an account? <a href="/auth/signup">Signup</a>
        </span>
      </form>
      <ToastContainer />
    </div>
  );
};

export default Login;
